mapper.select:
SELECT  FROM app_user u
JOIN organization o ON o.id=u.org_id JOIN app_user_security s ON s.user_id=u.id
WHERE u.username=#{username}

SELECT u.id,u.username,u.display_name,u.org_id,u.enabled,o.name AS org_name,s.auth_version
FROM app_user u JOIN organization o ON o.id=u.org_id JOIN app_user_security s ON s.user_id=u.id
ORDER BY u.id LIMIT #{limit} OFFSET #{offset}
